def write_view(*, repo_root: Path, view: str, filename: str, text: str) -> Path:
    """Write one generated closure view file."""
    target = repo_root / "catalog" / "views" / "closure" / view / filename
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(text, encoding="utf-8")
    return target


def write_view_payload(*, repo_root: Path, view: str, payload: dict) -> Path:
    """Write the machine-readable payload for one generated view."""
    target = repo_root / "catalog" / "views" / "closure" / view / "view.json"
    atomic_write_json(target, {"view": view, **payload})
    return target
